  for (let x = x0 + 1; x < x1; x++) if (!gap.includes(x)) w.set(x, y + 1, z1, ...B.fence("spruce"));
  for (const x of [x0, x1]) {
    w.set(x, y + 2, z1, ...B.fence("spruce"));
    w.set(x, y + 3, z1, ...B.lantern(false));
  }
  return finish(g, w);
}

