    if (!g.inBounds(x, y, z) || (!g.isAir(x, y, z) && !over.includes(bare(g.blockAt(x, y, z))))) {
      refused.push([x, y, z, block]);
      return false;
    }
    g.set(x, y, z, block, state, nbt);
    placed.push([x, y, z, block]);
    return true;
  };
  return { set, placed, refused };
