  const state = {};
  for (const [side, [dx, dz]] of Object.entries(SIDES)) {
    const id = bare(g.blockAt(x + dx, y, z + dz));
    state[side] = String(id === block || (id !== "air" && !NOT_SOLID.test(id)));
